Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -27,7 +27,135 @@
 <div class="overlay" id="overlay"><div class="card" id="startCard"><div class="bird-mark">🐦</div><div class="tag">The garden is waiting</div><h1>Ready to fly?</h1><p>Keep your wings moving and watch out for the thorny iron gates.</p><button class="primary" id="startBtn">START FLIGHT <span>↗</span></button><div class="hint">TAP ANYWHERE TO FLAP</div></div><div class="card" id="overCard" hidden><div class="tag">A little tumble</div><h1>Flight over</h1><p>The wild garden can be tricky. Take another run at it?</p><div class="result"><div><small>FLIGHT</small><strong id="finalScore">0</strong></div><div><small>BEST</small><strong id="finalBest">0</strong></div></div><div class="new-best" id="newBest" hidden>✦ NEW PERSONAL BEST ✦</div><button class="primary" id="retryBtn">FLY AGAIN <span>↗</span></button><div class="hint">TAP ANYWHERE TO FLAP</div></div><div class="card pausecard" id="pauseCard" hidden><div class="tag">Take a breather</div><h1>Paused</h1><p>Your bird is patiently waiting.</p><button class="primary" id="resumeBtn">KEEP FLYING <span>↗</span></button></div></div>
 </section>
 </main>
 <script>
-</script>
+(() => {
+  const canvas = document.getElementById('game');
+  const ctx = canvas.getContext('2d');
+  const overlay = document.getElementById('overlay');
+  const startCard = document.getElementById('startCard');
+  const overCard = document.getElementById('overCard');
+  const pauseCard = document.getElementById('pauseCard');
+  const scoreBox = document.getElementById('scoreDisplay');
+  const H = 760, FLOOR = 688, birdX = 112;
+  let W = 420, scale = 1, dpr = 1, state = 'ready', lastTime = 0;
+  let bird, gates = [], particles = [], clouds = [], score = 0, best = 0;
+  let speed = 178, gateGap = 197, spawnTimer = 0, groundScroll = 0;
+  let muted = false, audio = null, shake = 0, newRecord = false;
+  try { best = Number(localStorage.getItem('thornwing-best')) || 0; muted = localStorage.getItem('thornwing-muted') === 'true'; } catch (_) {}
+  document.getElementById('bestSide').textContent = best;
+  const soundBtn = document.getElementById('soundBtn');
+  soundBtn.textContent = muted ? '♫̸' : '♫';
+  soundBtn.setAttribute('aria-label', muted ? 'Turn sound on' : 'Turn sound off');
+  document.getElementById('pauseBtn').disabled = true;
+
+  function resize() {
+    const r = canvas.getBoundingClientRect();
+    dpr = Math.min(window.devicePixelRatio || 1, 2);
+    canvas.width = Math.round(r.width * dpr); canvas.height = Math.round(r.height * dpr);
+    scale = r.height / H; W = r.width / scale;
+    ctx.setTransform(dpr * scale, 0, 0, dpr * scale, 0, 0);
+    clouds = Array.from({length: 7}, (_, i) => ({x: (i * 113 + 18) % W, y: 120 + (i * 79) % 400, s: .6 + (i % 3) * .22}));
+  }
+  window.addEventListener('resize', resize); resize();
+
+  function reset() {
+    score = 0; speed = 178; gateGap = 197; spawnTimer = .75; gates = []; particles = []; shake = 0;
+    bird = {x: Math.min(birdX, W * .28), y: 342, vy: 0, angle: 0, wing: 0};
+    for (let i = 0; i < 3; i++) addGate(W + 95 + i * 295);
+    updateScore();
+  }
+  function addGate(x) {
+    const margin = 105;
+    const gapTop = margin + Math.random() * (FLOOR - margin * 2 - gateGap);
+    gates.push({x, gapTop, gapBottom: gapTop + gateGap, passed: false, sway: Math.random() * 6.28, flower: Math.random() > .5});
+  }
+  reset();
+
+  function showCard(which) {
+    overlay.classList.toggle('hidden', !which);
+    startCard.hidden = which !== 'start'; overCard.hidden = which !== 'over'; pauseCard.hidden = which !== 'pause';
+  }
+  function updateScore() { scoreBox.innerHTML = `FLIGHT<b>${score}</b>`; }
+  function startFlight() {
+    if (state === 'over') reset();
+    if (state === 'paused') { state = 'running'; showCard(null); return; }
+    if (state !== 'ready') return;
+    state = 'running'; showCard(null); document.getElementById('pauseBtn').disabled = false; flap();
+  }
+  function flap() {
+    if (state === 'ready') { startFlight(); return; }
+    if (state !== 'running') return;
+    bird.vy = -405; bird.wing = 1;
+    sound(540, .055, 'triangle', .035);
+    for (let i=0;i<3;i++) particles.push({x:bird.x-16,y:bird.y+4,vx:-45-Math.random()*45,vy:(Math.random()-.5)*70,life:.35,color:'#fff1bb',size:2+Math.random()*2});
+  }
+  function endFlight() {
+    if (state !== 'running') return;
+    state = 'over'; shake = 9; sound(135, .23, 'sawtooth', .045);
+    for (let i=0;i<14;i++) particles.push({x:bird.x,y:bird.y,vx:(Math.random()-.5)*210,vy:(Math.random()-.65)*220,life:.65+Math.random()*.4,color:['#ffe08a','#ef8066','#fff0c8'][i%3],size:2+Math.random()*4});
+    newRecord = score > best;
+    if (newRecord) { best = score; try {localStorage.setItem('thornwing-best', best)} catch (_) {} }
+    document.getElementById('bestSide').textContent = best;
+    document.getElementById('finalScore').textContent = score;
+    document.getElementById('finalBest').textContent = best;
+    document.getElementById('newBest').hidden = !newRecord;
+    document.getElementById('pauseBtn').disabled = true;
+    setTimeout(() => { if (state === 'over') showCard('over'); }, 420);
+  }
+  function pause() {
+    if (state === 'running') { state = 'paused'; showCard('pause'); }
+    else if (state === 'paused') { state = 'running'; showCard(null); }
+  }
+  function sound(freq, duration, type='sine', volume=.03) {
+    if (muted) return;
+    try {
+      audio ||= new (window.AudioContext || window.webkitAudioContext)();
+      if (audio.state === 'suspended') audio.resume();
+      const o=audio.createOscillator(), g=audio.createGain(); o.type=type; o.frequency.setValueAtTime(freq,audio.currentTime); o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.72),audio.currentTime+duration);
+      g.gain.setValueAtTime(volume,audio.currentTime); g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);
+      o.connect(g); g.connect(audio.destination); o.start(); o.stop(audio.currentTime+duration);
+    } catch (_) {}
+  }
+
+  document.getElementById('startBtn').addEventListener('click', startFlight);
+  document.getElementById('retryBtn').addEventListener('click', () => { state='ready'; reset(); showCard(null); startFlight(); });
+  document.getElementById('resumeBtn').addEventListener('click', pause);
+  document.getElementById('pauseBtn').addEventListener('click', pause);
+  soundBtn.addEventListener('click', () => { muted=!muted; soundBtn.textContent=muted?'♫̸':'♫'; soundBtn.setAttribute('aria-label',muted?'Turn sound on':'Turn sound off'); try{localStorage.setItem('thornwing-muted',muted)}catch(_){} if(!muted)sound(600,.08); });
+  document.querySelectorAll('button').forEach(b=>b.addEventListener('pointerdown',e=>e.stopPropagation()));
+  document.querySelector('.stage').addEventListener('pointerdown', e => {
+    if (e.target.closest('button')) return;
+    e.preventDefault();
+    if (state === 'ready') startFlight(); else if (state === 'over') { state='ready'; reset(); showCard(null); startFlight(); } else flap();
+  });
+  window.addEventListener('keydown', e => {
+    if (['Space','ArrowUp','KeyW'].includes(e.code)) {e.preventDefault(); if(state==='over'){state='ready';reset();showCard(null);startFlight();}else flap();}
+    if (e.code==='Escape' || e.code==='KeyP') pause();
+  });
+
+  function roundedRect(x,y,w,h,r,fill,stroke) {
+    ctx.beginPath(); ctx.roundRect(x,y,w,h,r); if(fill){ctx.fillStyle=fill;ctx.fill()} if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}
+  }
+  function cloud(x,y,s) {
+    ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#fff9e9';ctx.globalAlpha=.72;ctx.beginPath();ctx.ellipse(0,5,30,10,0,0,Math.PI*2);ctx.ellipse(-12,0,13,13,0,0,Math.PI*2);ctx.ellipse(3,-7,17,18,0,0,Math.PI*2);ctx.ellipse(19,1,13,12,0,0,Math.PI*2);ctx.fill();ctx.restore();
+  }
+  function background(dt) {
+    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#a8d7ce');sky.addColorStop(.55,'#d7e8d0');sky.addColorStop(1,'#f3d9a8');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
+    ctx.fillStyle='#fff1bf';ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(W*.77,174,48,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
+    if(state==='running'){for(const c of clouds){c.x-=dt*8;if(c.x<-60)c.x=W+50;}}
+    clouds.forEach(c=>cloud(c.x,c.y,c.s));
+    // soft far hills
+    ctx.fillStyle='#9dc4a5';ctx.beginPath();ctx.moveTo(0,490);for(let x=0;x<=W+20;x+=20)ctx.lineTo(x,470+Math.sin(x*.009+1)*23+Math.sin(x*.021)*9);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
+    ctx.fillStyle='#79ad8c';ctx.beginPath();ctx.moveTo(0,555);for(let x=0;x<=W+20;x+=20)ctx.lineTo(x,535+Math.sin(x*.012+2)*26+Math.sin(x*.027)*8);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
+    // distant garden trees
+    for(let i=0;i<Math.ceil(W/75)+2;i++){let x=((i*75-(groundScroll*.25)%75)+W+75)%W;ctx.fillStyle='#64947b';ctx.fillRect(x+22,482,5,83);ctx.beginPath();ctx.arc(x+24,480,22+(i%3)*3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8eb58c';ctx.beginPath();ctx.arc(x+13,473,12,0,Math.PI*2);ctx.fill();}
+    // foreground sod and tiny flowers
+    ctx.fillStyle='#729967';ctx.fillRect(0,FLOOR,W,H-FLOOR);
+    ctx.fillStyle='#92ad6d';ctx.fillRect(0,FLOOR,W,8);
+    ctx.fillStyle='#e2c47e';ctx.fillRect(0,FLOOR+8,W,5);
+    const scroll=groundScroll%44;
+    for(let x=-scroll;x<W+44;x+=44){ctx.fillStyle='#5e875f';ctx.beginPath();ctx.ellipse(x+8,FLOOR+20,15,4,-.17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7d58b';ctx.beginPath();ctx.arc(x+30,FLOOR+28,2.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f2f0cf';ctx.beginPath();ctx.arc(x+35,FLOOR+28,2,0,Math.PI*2);ctx.fill();}
+  }
+
 </body>
 </html>

