  }
  function drawGate(g) {
    const x=g.x, w=72, topEnd=g.gapTop, bottomStart=g.gapBottom;
    const steel=ctx.createLinearGradient(x,0,x+w,0);steel.addColorStop(0,'#314750');steel.addColorStop(.22,'#647b7b');steel.addColorStop(.55,'#40595e');steel.addColorStop(.82,'#718682');steel.addColorStop(1,'#344b52');
    function segment(y1,y2,top) {
      if(y2<=y1)return;
      ctx.fillStyle=steel;ctx.fillRect(x+4,y1,w-8,y2-y1);
      ctx.fillStyle='#213b43';ctx.fillRect(x,y1,5,y2-y1);ctx.fillRect(x+w-5,y1,5,y2-y1);
      // iron uprights, softly lit along one edge
      for(let bx=x+11;bx<x+w-5;bx+=10){ctx.fillStyle='#273f46';ctx.fillRect(bx,y1,4,y2-y1);ctx.fillStyle='#a1aaa0';ctx.globalAlpha=.6;ctx.fillRect(bx+1,y1,1,y2-y1);ctx.globalAlpha=1;}
      // crossbars with small rivets
      const ys=[y1+12,y1+(y2-y1)*.52,y2-12].filter(y=>y>y1+3&&y<y2-3);
      ys.forEach(y=>{ctx.fillStyle='#263f46';ctx.fillRect(x+3,y-3,w-6,7);ctx.fillStyle='#9ca99e';ctx.fillRect(x+3,y-3,w-6,2);for(let bx=x+10;bx<x+w-7;bx+=12){ctx.fillStyle='#d3bd85';ctx.beginPath();ctx.arc(bx,y,1.3,0,Math.PI*2);ctx.fill();}});
      // capped ends and little spear finials on the outside edge
      ctx.fillStyle='#354e53';ctx.fillRect(x-4,top?y2-7:y1,w+8,8);
      if(top){for(let bx=x+5;bx<x+w-4;bx+=13){ctx.beginPath();ctx.moveTo(bx,y1+4);ctx.lineTo(bx+4,y1-9);ctx.lineTo(bx+8,y1+4);ctx.fillStyle='#526e70';ctx.fill();}}
    }
    segment(0,topEnd,true); segment(bottomStart,FLOOR,false);
    // inward-facing thorn tips along the narrow opening
    ctx.fillStyle='#344d52';ctx.strokeStyle='#9aa79b';ctx.lineWidth=1;
    for(let bx=x+5;bx<x+w-3;bx+=13){
      ctx.beginPath();ctx.moveTo(bx,g.gapTop-1);ctx.lineTo(bx+5,g.gapTop+17);ctx.lineTo(bx+10,g.gapTop-1);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(bx+4,g.gapTop+7);ctx.lineTo(bx+5,g.gapTop+17);ctx.stroke();
      ctx.beginPath();ctx.moveTo(bx,g.gapBottom+1);ctx.lineTo(bx+5,g.gapBottom-17);ctx.lineTo(bx+10,g.gapBottom+1);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(bx+4,g.gapBottom-8);ctx.lineTo(bx+5,g.gapBottom-17);ctx.stroke();
    }
    // a tiny climbing vine and leaves add garden whimsy
    if(g.flower){ctx.strokeStyle='#77966d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+w-2,g.gapTop-28);ctx.bezierCurveTo(x+w+7,g.gapTop-20,x+w-8,g.gapTop-11,x+w-1,g.gapTop-3);ctx.stroke();ctx.fillStyle='#9bb477';ctx.beginPath();ctx.ellipse(x+w+1,g.gapTop-20,5,2,-.6,0,Math.PI*2);ctx.ellipse(x+w-5,g.gapTop-12,5,2,.6,0,Math.PI*2);ctx.fill();}
  }
  function drawBird(time) {
    const bob=state==='ready'?Math.sin(time*.004)*5:0;
    ctx.save();ctx.translate(bird.x,bird.y+bob);ctx.rotate(bird.angle);
    // tail feathers
    ctx.fillStyle='#e4814f';ctx.beginPath();ctx.moveTo(-14,-3);ctx.lineTo(-27,-11);ctx.lineTo(-23,1);ctx.lineTo(-29,7);ctx.lineTo(-12,7);ctx.closePath();ctx.fill();
    // body
    ctx.fillStyle='#e9954f';ctx.beginPath();ctx.ellipse(-1,1,18,14,-.12,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ffe0a0';ctx.beginPath();ctx.ellipse(2,7,10,7,.2,0,Math.PI*2);ctx.fill();
    // wing lifts with flap and settles on descent
    const wingAngle=state==='ready'?Math.sin(time*.009)*.4:(bird.wing>0?-.55:Math.min(.6,bird.vy/600));
    ctx.save();ctx.translate(-5,1);ctx.rotate(wingAngle);ctx.fillStyle='#c56c42';ctx.beginPath();ctx.ellipse(0,2,10,6,-.18,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f0b46a';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(-5,2);ctx.lineTo(1,4);ctx.moveTo(-2,-1);ctx.lineTo(4,2);ctx.stroke();ctx.restore();
    // round head + bright curious eye
    ctx.fillStyle='#f4b65f';ctx.beginPath();ctx.arc(7,-7,11,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff9df';ctx.beginPath();ctx.arc(11,-9,4.7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#27383a';ctx.beginPath();ctx.arc(12.4,-9,2,0,Math.PI*2);ctx.fill();
    // beak
    ctx.fillStyle='#e86f53';ctx.beginPath();ctx.moveTo(16,-5);ctx.lineTo(27,-2);ctx.lineTo(17,2);ctx.closePath();ctx.fill();
    ctx.restore();
  }
  function circleRect(cx,cy,r,x,y,w,h){const px=Math.max(x,Math.min(cx,x+w)),py=Math.max(y,Math.min(cy,y+h));return (cx-px)**2+(cy-py)**2<r*r;}
  function update(dt,time) {
    if(state==='running'){
      bird.vy+=1080*dt;bird.y+=bird.vy*dt;bird.angle=Math.max(-.55,Math.min(1.05,bird.vy/560));bird.wing=Math.max(0,bird.wing-dt*3.2);
      groundScroll+=speed*dt;spawnTimer-=dt;
      if(spawnTimer<=0){addGate(W+80);spawnTimer=295/speed;}
      for(const g of gates){g.x-=speed*dt;if(!g.passed&&g.x+72<bird.x){g.passed=true;score++;updateScore();sound(780,.09,'sine',.04);if(score%4===0){speed=Math.min(250,speed+7);gateGap=Math.max(166,gateGap-4);}}}
      gates=gates.filter(g=>g.x>-90);
      if(bird.y-12<0||bird.y+12>FLOOR)endFlight();
      for(const g of gates){
        if(bird.x+12>g.x&&bird.x-12<g.x+72&&(bird.y-12<g.gapTop+17||bird.y+12>g.gapBottom-17)){endFlight();break;}
        if(circleRect(bird.x,bird.y,11,g.x,0,5,g.gapTop)||circleRect(bird.x,bird.y,11,g.x+67,0,5,g.gapTop)||circleRect(bird.x,bird.y,11,g.x,FLOOR,gapW(),H-FLOOR)) { /* frame detail is covered by the gate clearance above */ }
      }
    }
    if(state==='over'){bird.vy+=900*dt;bird.y=Math.min(FLOOR-14,bird.y+bird.vy*dt);bird.angle=Math.min(1.3,bird.angle+dt*1.6);}
    for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;p.life-=dt;}
    particles=particles.filter(p=>p.life>0);
    shake=Math.max(0,shake-dt*28);
  }
  function gapW(){return 5;}
  function render(time,dt) {
    ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);
    background(dt);
    gates.forEach(drawGate);
    // softly drifting seed fluff
    for(let i=0;i<5;i++){const x=((i*137+time*.012)%W),y=230+(i*91)%370+Math.sin(time*.001+i)*8;ctx.globalAlpha=.45;ctx.fillStyle='#fff8dc';ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
    for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*Math.min(1,p.life*2),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    drawBird(time);
    // ground edge dandelion tufts
    for(let x=-(groundScroll%86);x<W+86;x+=86){ctx.strokeStyle='#476d53';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+45,FLOOR+8);ctx.lineTo(x+41,FLOOR-2);ctx.moveTo(x+45,FLOOR+8);ctx.lineTo(x+49,FLOOR-4);ctx.stroke();ctx.fillStyle='#f4df9b';ctx.beginPath();ctx.arc(x+41,FLOOR-2,2,0,Math.PI*2);ctx.arc(x+49,FLOOR-4,2,0,Math.PI*2);ctx.fill();}
    ctx.restore();
  }
  function frame(now) {
    const dt=Math.min(.034,(now-lastTime)/1000||0);lastTime=now;
    update(dt,now);render(now,dt);requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>

